 if(!Recognition){returnAuto('이 브라우저는 음성 인식을 지원하지 않습니다. 자동 스크롤로 이어갑니다.');return;}
 stopRecognition();const epoch=voiceEpoch;const recognition=new Recognition();recognizer=recognition;const bases=new Map();
